CREATE TABLE "ExternalTrade" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"tradeNumber" TEXT NOT NULL,"tradeDate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"tradeType" TEXT NOT NULL,"itemId" INTEGER NOT NULL,"entityName" TEXT NOT NULL,"quantity" DECIMAL NOT NULL,"unitPrice" DECIMAL NOT NULL,"totalAmount" DECIMAL NOT NULL,"referenceNumber" TEXT,"notes" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "ExternalTrade_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "Item"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "ExternalLinkedCost" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"costNumber" TEXT NOT NULL,"costDate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"externalTradeId" INTEGER,"itemId" INTEGER NOT NULL,"costType" TEXT NOT NULL,"entityName" TEXT,"description" TEXT,"amount" DECIMAL NOT NULL,"paymentMethod" TEXT,"notes" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ExternalLinkedCost_externalTradeId_fkey" FOREIGN KEY ("externalTradeId") REFERENCES "ExternalTrade"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "ExternalLinkedCost_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "Item"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "ExternalExpense" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"expenseNumber" TEXT NOT NULL,"expenseDate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"entityName" TEXT,"description" TEXT NOT NULL,"category" TEXT NOT NULL,"amount" DECIMAL NOT NULL,"paymentMethod" TEXT,"referenceNumber" TEXT,"notes" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "ExternalTrade_tradeNumber_key" ON "ExternalTrade"("tradeNumber");CREATE INDEX "ExternalTrade_tradeDate_idx" ON "ExternalTrade"("tradeDate");CREATE INDEX "ExternalTrade_itemId_tradeType_idx" ON "ExternalTrade"("itemId","tradeType");CREATE UNIQUE INDEX "ExternalLinkedCost_costNumber_key" ON "ExternalLinkedCost"("costNumber");CREATE INDEX "ExternalLinkedCost_costDate_idx" ON "ExternalLinkedCost"("costDate");CREATE INDEX "ExternalLinkedCost_itemId_idx" ON "ExternalLinkedCost"("itemId");CREATE UNIQUE INDEX "ExternalExpense_expenseNumber_key" ON "ExternalExpense"("expenseNumber");CREATE INDEX "ExternalExpense_expenseDate_idx" ON "ExternalExpense"("expenseDate");CREATE INDEX "ExternalExpense_category_idx" ON "ExternalExpense"("category");
